ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS entity_name text DEFAULT 'OSANVAULT AFRICA LTD';
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS jurisdiction text DEFAULT 'Nigeria';
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS action_name text;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS approver_role text;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS threshold_amount numeric;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS currency text DEFAULT 'NGN';
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS dual_control boolean DEFAULT false;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS board_reserved boolean DEFAULT false;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS legal_review boolean DEFAULT false;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS evidence_required text;
ALTER TABLE authority_matrix ADD COLUMN IF NOT EXISTS notes text;
